#!/usr/bin/env python3
"""Cross-FW diff of Poopsploit shellcode embedded patch offsets.
Extracts from each FW's shellcode hex the [rcx+OFF] displacement of every
mem write (rcx = kernel_base via LSTAR-0x1c0), plus the `add rdx,imm`
that encodes JMP_RSI. Prints a per-offset table so 13.50->13.52 movement
is visible."""

import re, sys
from capstone import Cs, CS_ARCH_X86, CS_MODE_64

FW = {
"9.00": "",
"12.00": "",
"13.00": "",
"13.02": "",
"13.50": "",
"13.52": "",
}

md = Cs(CS_ARCH_X86, CS_MODE_64)

def patches(hexs):
    """Return dict offset->(mnemonic, op_str, bytes-write-size) for all
    [rcx+imm] mem writes + add rdx imm (JMP_RSI encode)."""
    raw = bytes.fromhex(hexs)
    out = {}
    jmp_rsi = None
    for i in md.disasm(raw, 0):
        op = i.op_str
        m = re.search(r"\[rcx \+ 0x([0-9a-f]+)\]", op)
        if m:
            off = int(m.group(1), 16)
            sz = "dword" if i.mnemonic.startswith("mov dword") else ("word" if "word" in i.mnemonic else "byte")
            out[off] = f"{i.mnemonic} {op}"
        if i.mnemonic == "add" and op.startswith("rdx"):
            jmp_rsi = int(re.search(r"0x([0-9a-f]+)", op).group(1), 16) + 0x1c0
    return out, jmp_rsi

sets = {}
for fw, hx in FW.items():
    p, jr = patches(hx)
    sets[fw] = p
    print(f"{fw}: {len(p)} patches, JMP_RSI(rdx-encoded) = 0x{jr:x}")

fws = list(FW)
keys = sorted(set().union(*sets.values()))
print("\n=== offset matrix (x = present) ===")
print(f"{'offset':>9} " + " ".join(f"{f:>6}" for f in fws))
for k in keys:
    row = [f"{'x':>6}" if k in sets[f] else f"{'':>6}" for f in fws]
    print(f"0x{k:07x} " + " ".join(row))

print("\n=== JMP_RSI per FW ===")
for fw in fws:
    _, jr = patches(FW[fw])
    print(f"{fw}: 0x{jr:x}")
